        --
        -- Name: mention_notify(); Type: FUNCTION; Schema: audit; Owner: postgres
        --

        CREATE FUNCTION audit.mention_notify() RETURNS trigger
            LANGUAGE plpgsql
            AS $$
        DECLARE 
        ID BIGINT ; 
        mention_id BIGINT ;
        transaction_id BIGINT;
        BEGIN

        -- For UPDATE operation, we only notify when *processing* field is reset from TRUE to FALSE.
        IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND NEW.processing = FALSE AND OLD.processing = TRUE) THEN
            ID = NEW.ID ; 
            mention_id = NEW.mention_id ;
            transaction_id = NEW.transaction_id;
        ELSIF TG_OP = 'DELETED' THEN
            ID = OLD.ID ; 
            mention_id = OLD.mention_id ;
            transaction_id = OLD.transaction_id;
        END IF ; 
        
        IF mention_id IS NOT NULL THEN
            perform pg_notify(TG_TABLE_NAME || '_update', json_build_object('table', TG_TABLE_NAME, 'id', ID, 'mention_id', mention_id, 'type', TG_OP, 'transaction_id', transaction_id) :: TEXT) ; 
            RETURN NEW ;
        ELSE
            RETURN NULL;
        END IF;
        END  
        $$;


        ALTER FUNCTION audit.mention_notify() OWNER TO postgres;

        --
        -- Name: calculate_end_date(timestamp without time zone, json); Type: FUNCTION; Schema: public; Owner: postgres
        --

        CREATE FUNCTION public.calculate_end_date(start_time timestamp without time zone, mention_snippets json) RETURNS timestamp without time zone
            LANGUAGE plpgsql
            AS $$
        DECLARE
        s FLOAT;
        e FLOAT;
        i JSON;
        BEGIN
        FOR i IN SELECT * FROM json_array_elements(mention_snippets)
        LOOP
            IF s IS NULL OR (i->>'startTime')::TEXT::NUMERIC < s THEN
            s = (i->>'startTime')::TEXT::NUMERIC;
            END IF;
            IF e IS NULL OR (i->>'endTime')::TEXT::NUMERIC > e THEN
            e = (i->>'endTime')::TEXT::NUMERIC;
            END IF;
            --RAISE NOTICE 'startTime = %; endTime = %; s = %; e = %', i->>'startTime', i->>'endTime', s, e;
        END LOOP;
        RETURN start_time + ((e - s) * INTERVAL '1 second');
        END
        $$;


        ALTER FUNCTION public.calculate_end_date(start_time timestamp without time zone, mention_snippets json) OWNER TO postgres;

        --
        -- Name: duplicate_mention_check(); Type: FUNCTION; Schema: public; Owner: postgres
        --

        CREATE FUNCTION public.duplicate_mention_check() RETURNS trigger
            LANGUAGE plpgsql
            AS $$
        BEGIN
            IF NEW.mention_end_date IS NULL THEN
                NEW.mention_end_date := calculate_end_date(NEW.mention_date, NEW.mention_snippets);
            END IF;
            --RAISE NOTICE 'mention_date = %, mention_end_date = %', NEW.mention_date, NEW.mention_end_date;
            IF NEW.media_source_id != -1 AND EXISTS (SELECT 1 FROM mention WHERE tracking_unit_id = NEW.tracking_unit_id AND media_source_id = NEW.media_source_id AND (NEW.mention_date < mention_end_date) AND (NEW.mention_end_date > mention_date)) THEN
                RAISE EXCEPTION 'Duplicate mention!';
                --RAISE NOTICE 'Duplicate mention detected; skipping insert!';
                --RETURN NULL;
            ELSEIF NEW.media_source_id = -1 AND EXISTS (SELECT 1 FROM mention WHERE tracking_unit_id = NEW.tracking_unit_id AND media_source_id = -1 AND (NEW.mention_date < mention_end_date) AND (NEW.mention_end_date > mention_date) AND media_id = NEW.media_id) THEN
                RAISE EXCEPTION 'Duplicate private mention!';
                --RAISE NOTICE 'Duplicate mention detected; skipping insert!';
                --RETURN NULL;
            END IF;
            --RAISE EXCEPTION 'bailey force error';
            RETURN NEW;
        END
        $$;


        ALTER FUNCTION public.duplicate_mention_check() OWNER TO postgres;

        --
        -- Name: hstore_add(public.hstore, public.hstore); Type: FUNCTION; Schema: public; Owner: postgres
        --

        CREATE FUNCTION public.hstore_add(a public.hstore, b public.hstore) RETURNS public.hstore
            LANGUAGE plpgsql IMMUTABLE
            AS $$
        BEGIN
            RETURN
                hstore(
                array_agg(key),
                    array_agg(
                    (
                        COALESCE(r.value::integer, 0) +
                        COALESCE(l.value::integer, 0)
                    )::text
                )
            )
            FROM each(a) l
            FULL OUTER JOIN each(b) r
            USING (key);
        END;
        $$;


        ALTER FUNCTION public.hstore_add(a public.hstore, b public.hstore) OWNER TO postgres;

        --
        -- Name: json_object_set_key(json, text, anyelement); Type: FUNCTION; Schema: public; Owner: postgres
        --

        CREATE FUNCTION public.json_object_set_key("json" json, key_to_set text, value_to_set anyelement) RETURNS json
            LANGUAGE sql IMMUTABLE STRICT
            AS $$
        SELECT concat('{', string_agg(to_json("key") || ':' || "value", ','), '}')::json
        FROM (SELECT *
                FROM json_each("json")
                WHERE "key" <> "key_to_set"
                UNION ALL
                SELECT "key_to_set", to_json("value_to_set")) AS "fields"
        $$;


        ALTER FUNCTION public.json_object_set_key("json" json, key_to_set text, value_to_set anyelement) OWNER TO postgres;

        --
        -- Name: json_object_update_key(json, text, anyelement); Type: FUNCTION; Schema: public; Owner: postgres
        --

        CREATE FUNCTION public.json_object_update_key("json" json, key_to_set text, value_to_set anyelement) RETURNS json
            LANGUAGE sql IMMUTABLE STRICT
            AS $$
        SELECT CASE
        WHEN ("json" -> "key_to_set") IS NULL THEN "json"
        ELSE (SELECT concat('{', string_agg(to_json("key") || ':' || "value", ','), '}')
                FROM (SELECT *
                        FROM json_each("json")
                        WHERE "key" <> "key_to_set"
                        UNION ALL
                        SELECT "key_to_set", to_json("value_to_set")) AS "fields")::json
        END
        $$;


        ALTER FUNCTION public.json_object_update_key("json" json, key_to_set text, value_to_set anyelement) OWNER TO postgres;

        --
        -- Name: jsonb_merge(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
        --

        CREATE FUNCTION public.jsonb_merge("left" jsonb, "right" jsonb) RETURNS jsonb
            LANGUAGE sql IMMUTABLE STRICT
            AS $_$
        SELECT
        CASE WHEN jsonb_typeof($1) = 'object' AND jsonb_typeof($2) = 'object' THEN
            (SELECT json_object_agg(COALESCE(o.key, n.key), CASE WHEN n.key IS NOT NULL THEN n.value ELSE o.value END)::jsonb
                FROM jsonb_each($1) o
                FULL JOIN jsonb_each($2) n ON (n.key = o.key))
        ELSE
            (CASE WHEN jsonb_typeof($1) = 'array' THEN LEFT($1::text, -1) ELSE '['||$1::text END ||', '||
            CASE WHEN jsonb_typeof($2) = 'array' THEN RIGHT($2::text, -1) ELSE $2::text||']' END)::jsonb
        END
        $_$;


        ALTER FUNCTION public.jsonb_merge("left" jsonb, "right" jsonb) OWNER TO postgres;

        --
        -- Name: mark_mentions_as_modified1(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
        --

        CREATE FUNCTION public.mark_mentions_as_modified1(integer, integer) RETURNS integer
            LANGUAGE plpgsql
            AS $_$
        DECLARE
            count integer;
        BEGIN
            UPDATE mention
            SET mention_state_lookup_id = 4
            WHERE mention_id IN (
                SELECT mention_id
                FROM mention
                WHERE (mention_state_lookup_id = 1 OR mention_state_lookup_id IS NULL)
                AND (user_snippets IS NOT NULL OR mention_status_id <> 1)
                AND tracking_unit_id = $1
                LIMIT $2
            );
            
            GET DIAGNOSTICS count = ROW_COUNT;
            RETURN count;
        END;
        $_$;


        ALTER FUNCTION public.mark_mentions_as_modified1(integer, integer) OWNER TO postgres;

        --
        -- Name: media_weekly_id(); Type: FUNCTION; Schema: public; Owner: postgres
        --

        CREATE FUNCTION public.media_weekly_id() RETURNS trigger
            LANGUAGE plpgsql
            AS $$
        DECLARE
            base_date   date;
            week_offset integer;
            days_diff   integer;
            weeks_diff   integer;

            base_val    integer;
            next_val    integer;
        BEGIN
            -- W,WW0,000,000 - format
            -- 2,147 483 647 - max signed int4
            -- 0,200,000,000 - proposed start for PROD (at offset start 020, max 214 with 7.48m ids)
            ---0,400,127,638 - (proposed start: WWW=044) max recording id in DEV (as of oct. 17, 2018)
            -- 0,400,009,602 - (proposed start: WWW=041) max recording id in STAGE (as of oct. 24, 2018)
            -- 0,119,822,400 - (proposed start: WWW=020) max recording id in PROD (as of oct. 26, 2018)
            -- 0,500,132,931 -- (proposed start: WWW=052) max recording id in UK-PROD (as of oct. 26, 2018)
            -- base_val is the minimal value of the sequence for the current week: WWW0000000
            base_date := date('2018-10-22 +00:00'); -- week 43, 2018
            week_offset := 20; -- offset by, usually the next whole number of max recording of the ENV

            -- now() is a timestamp type, explicit cast to timestamp math
            days_diff := EXTRACT('days' FROM now() - base_date::timestamp);
            weeks_diff := (days_diff / 7)::int;

            base_val := (week_offset + weeks_diff) * 10000000;
            next_val := nextval('media_weekly_id_sequence');
            -- note: currval differs per db session, requires nextval
            -- which is atomic distinct.
            -- so if the next sequence is less, then update it and
            -- use that as new media id
            IF (next_val < base_val) THEN
                PERFORM setval('media_weekly_id_sequence', base_val);
                NEW.media_id := base_val;
            ELSE
                NEW.media_id := next_val;
            END IF;

            RETURN NEW;
        END; $$;


        ALTER FUNCTION public.media_weekly_id() OWNER TO postgres;

