        --

        CREATE FUNCTION public.refresh_program_to_tracking_unit_view() RETURNS trigger
            LANGUAGE plpgsql
            AS $$
        declare 
            should_run boolean default false;
            lock_id integer default 123456;
        begin
            select pg_try_advisory_xact_lock(lock_id) into should_run;
            if should_run then
            REFRESH MATERIALIZED VIEW _view_program_to_tracking_unit;
            end if;
        RETURN NULL;
        END $$;


