        --
        -- Name: trigger_set_timestamp(); Type: FUNCTION; Schema: public; Owner: postgres
        --

        CREATE FUNCTION public.trigger_set_timestamp() RETURNS trigger
            LANGUAGE plpgsql
            AS $$
        begin
        -- avoid processing when we transition mention to PENDING_DELETE.  mention-gen frequently transitioned all mentions for a tracking
        -- unit to PENDING_DELETE while it runs mention-gen.  This unnecessary update to updated_at and created_at could trigger other processing to kick in.
            IF TG_OP = 'UPDATE' AND NEW.mention_state_lookup_id=3 AND OLD.mention_state_lookup_id<>3 THEN
            RETURN NEW;
        ELSE
            NEW.updated_at = NOW();
            IF NEW.created_at IS NULL THEN
                NEW.created_at = NOW();
            END IF;
            RETURN NEW;
        END IF;
        END;
        $$;


        ALTER FUNCTION public.trigger_set_timestamp() OWNER TO postgres;

