        --
        -- Name: update_mentions1(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
        --

        CREATE FUNCTION public.update_mentions1(integer, integer) RETURNS integer
            LANGUAGE plpgsql
            AS $_$
        DECLARE
            n int;
            t int;
            tu record;
        BEGIN
            t := 0;
            
            FOR tu IN
                select tracking_unit_id
                from tracking_unit
                where tracking_unit_id between $1 and $2
                order by tracking_unit_id
            LOOP
                RAISE NOTICE 'tracking unit %', tu.tracking_unit_id;
                
                n := 50000;
                WHILE n = 50000 LOOP
                    n := mark_mentions_as_modified1(tu.tracking_unit_id, 50000);
                    t := t + n;
            
                    RAISE NOTICE '% mentions updated (% total)', n, t;
                END LOOP;
                
            END LOOP;

            RETURN t;
        END;
        $_$;


        ALTER FUNCTION public.update_mentions1(integer, integer) OWNER TO postgres;

        --
        -- Name: update_program_sequence_column(); Type: FUNCTION; Schema: public; Owner: postgres
        --

        CREATE FUNCTION public.update_program_sequence_column() RETURNS trigger
            LANGUAGE plpgsql
            AS $$
        BEGIN
        NEW.program_sequence = CASE
            -- letters first
            WHEN (ASCII(SUBSTR(NEW.program_name, 1, 1)) BETWEEN 65 AND 90) OR (ASCII(SUBSTR(NEW.program_name, 1, 1)) BETWEEN 97 AND 122) THEN 0
            -- then numbers
            WHEN ASCII(SUBSTR(NEW.program_name, 1, 1)) BETWEEN 48 AND 57 THEN 1

            ELSE 2
        END;
        RETURN NEW;
        END;
        $$;


        ALTER FUNCTION public.update_program_sequence_column() OWNER TO postgres;

