        --
        -- Name: _view_program_to_tracking_unit; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
        --

        CREATE MATERIALIZED VIEW public._view_program_to_tracking_unit AS
        SELECT p.program_id,
            tup.tracking_unit_id
        FROM (public.program p
            JOIN public.tracking_unit_program tup ON ((tup.program_id = p.program_id)))
        UNION
        SELECT p.program_id,
            tu.tracking_unit_id
        FROM ((((public.program p
            JOIN public.program_schedule ps ON ((ps.program_id = p.program_id)))
            JOIN public.media_source ms ON ((ms.media_source_id = ps.media_source_id)))
            JOIN public.tracking_unit_market tum ON ((tum.market_id = ms.home_market_id)))
            JOIN public.tracking_unit tu ON ((tum.tracking_unit_id = tu.tracking_unit_id)))
        WHERE ((COALESCE(p.is_national, false) <> true) AND (NOT (EXISTS ( SELECT 'x'
                FROM public.tracking_unit_program tup
                WHERE (tup.tracking_unit_id = tu.tracking_unit_id)))))
        UNION
        SELECT p.program_id,
            tu.tracking_unit_id
        FROM (((public.tracking_unit_media_source tums
            JOIN public.program_schedule ps ON ((ps.media_source_id = tums.media_source_id)))
            JOIN public.program p ON ((p.program_id = ps.program_id)))
            JOIN public.tracking_unit tu ON ((tu.tracking_unit_id = tums.tracking_unit_id)))
        WHERE (COALESCE(p.is_national, false) <> true)
        UNION
        SELECT (mst.media_source_type_id * '-100'::integer) AS program_id,
            tu.tracking_unit_id
        FROM (public.tracking_unit tu
            JOIN public.media_source_type mst ON ((mst.media_source_type_id = ANY (tu.media_source_type_ids))))
        WHERE ((NOT (EXISTS ( SELECT 'x'
                FROM public.tracking_unit_program
                WHERE (tracking_unit_program.tracking_unit_id = tu.tracking_unit_id)))) AND (NOT (EXISTS ( SELECT 'x'
                FROM public.tracking_unit_market
                WHERE (tracking_unit_market.tracking_unit_id = tu.tracking_unit_id)))) AND (NOT (EXISTS ( SELECT 'x'
                FROM public.tracking_unit_media_source
                WHERE (tracking_unit_media_source.tracking_unit_id = tu.tracking_unit_id)))) AND ((NOT (EXISTS ( SELECT 'x'
                FROM public.tracking_unit_program
                WHERE (tracking_unit_program.tracking_unit_id = tu.tracking_unit_id)))) OR (NOT (EXISTS ( SELECT 'x'
                FROM ((public.tracking_unit_program tup
                    JOIN public.tracking_unit t ON ((t.tracking_unit_id = tup.tracking_unit_id)))
                    JOIN public.program p ON ((p.program_id = tup.program_id)))
                WHERE ((tup.tracking_unit_id = tu.tracking_unit_id) AND (p.media_source_type_id = ANY (tu.media_source_type_ids))))))))
        WITH NO DATA;


        ALTER TABLE public._view_program_to_tracking_unit OWNER TO postgres;

