        --
        -- Name: advertiser advertiser_pkey; Type: CONSTRAINT; Schema: public; Owner: postgres
        --

        ALTER TABLE ONLY public.advertiser
            ADD CONSTRAINT advertiser_pkey PRIMARY KEY (advertiser_id);


        --
        -- Name: organization organization_pkey; Type: CONSTRAINT; Schema: public; Owner: postgres
        --

        ALTER TABLE ONLY public.organization
            ADD CONSTRAINT organization_pkey PRIMARY KEY (organization_id);


        --
        -- Name: analytics_rollup_by_advertiser; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
        --

        CREATE MATERIALIZED VIEW public.analytics_rollup_by_advertiser AS
        WITH temp_mention AS (
                SELECT mention.tracking_unit_id,
                    count(mention.tracking_unit_id) AS mentions
                FROM public.mention
                GROUP BY mention.tracking_unit_id
                )
        SELECT o.organization_id,
            o.organization_name AS organization,
            COALESCE((o.kvp ->> 'image'::text), ''::text) AS organization_image,
            COALESCE((o.kvp ->> 'dataSources'::text), ''::text) AS organization_datasources,
            a.advertiser_id,
            a.advertiser_name AS advertiser,
            COALESCE(a.advertiser_image, ''::text) AS advertiser_image,
            COALESCE(a.advertiser_description, ''::text) AS advertiser_description,
            COALESCE(a.advertiser_website_url, ''::text) AS advertiser_url,
            sum(tm.mentions) AS mentions,
            count(DISTINCT c.campaign_id) AS campaign_count,
            count(DISTINCT b.brand_id) AS brand_count,
            count(DISTINCT tu.tracking_unit_id) AS tracking_unit_count,
            count(DISTINCT
                CASE
                    WHEN (tu.media_source_type_id = 1) THEN tu.tracking_unit_id
                    ELSE NULL::integer
                END) AS radio_count,
            count(DISTINCT
                CASE
                    WHEN (tu.media_source_type_id = 2) THEN tu.tracking_unit_id
                    ELSE NULL::integer
                END) AS broadcast_tv_count,
            count(DISTINCT
                CASE
                    WHEN (tu.media_source_type_id = 3) THEN tu.tracking_unit_id
                    ELSE NULL::integer
                END) AS youtube_count,
            count(DISTINCT
                CASE
                    WHEN (tu.media_source_type_id = 4) THEN tu.tracking_unit_id
                    ELSE NULL::integer
                END) AS podcast_count,
            ( SELECT sum(campaign.campaign_budget) AS sum
                FROM public.campaign
                WHERE (a.advertiser_id = campaign.advertiser_id)) AS campaign_budget
        FROM (((((public.organization o
            JOIN public.advertiser a ON ((a.organization_id = o.organization_id)))
            LEFT JOIN public.brand b ON ((b.advertiser_id = a.advertiser_id)))
            LEFT JOIN public.campaign c ON ((c.brand_id = b.brand_id)))
            LEFT JOIN public.tracking_unit tu ON ((tu.campaign_id = c.campaign_id)))
            LEFT JOIN temp_mention tm ON ((tm.tracking_unit_id = tu.tracking_unit_id)))
        GROUP BY o.organization_id, a.advertiser_id
        WITH NO DATA;


        ALTER TABLE public.analytics_rollup_by_advertiser OWNER TO postgres;

        --
        -- Name: brand brand_pkey; Type: CONSTRAINT; Schema: public; Owner: postgres
        --

        ALTER TABLE ONLY public.brand
            ADD CONSTRAINT brand_pkey PRIMARY KEY (brand_id);


        --
        -- Name: analytics_rollup_by_brand; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
        --

        CREATE MATERIALIZED VIEW public.analytics_rollup_by_brand AS
        WITH temp_mention AS (
                SELECT mention.tracking_unit_id,
                    count(mention.tracking_unit_id) AS mentions
                FROM public.mention
                GROUP BY mention.tracking_unit_id
                )
        SELECT o.organization_id,
            a.advertiser_id,
            b.brand_id,
            b.brand_name AS brand,
            COALESCE(b.brand_image, ''::text) AS brand_image,
            COALESCE(b.brand_description, ''::text) AS brand_description,
            COALESCE(b.brand_website_url, ''::text) AS brand_url,
            sum(tm.mentions) AS mentions,
            count(DISTINCT c.campaign_id) AS campaign_count,
            count(DISTINCT b.brand_id) AS brand_count,
            count(DISTINCT tu.tracking_unit_id) AS tracking_unit_count,
            count(DISTINCT
                CASE
                    WHEN (tu.media_source_type_id = 1) THEN tu.tracking_unit_id
                    ELSE NULL::integer
                END) AS radio_count,
            count(DISTINCT
                CASE
                    WHEN (tu.media_source_type_id = 2) THEN tu.tracking_unit_id
                    ELSE NULL::integer
                END) AS broadcast_tv_count,
            count(DISTINCT
                CASE
                    WHEN (tu.media_source_type_id = 3) THEN tu.tracking_unit_id
                    ELSE NULL::integer
                END) AS youtube_count,
            count(DISTINCT
                CASE
                    WHEN (tu.media_source_type_id = 4) THEN tu.tracking_unit_id
                    ELSE NULL::integer
                END) AS podcast_count,
            ( SELECT sum(campaign.campaign_budget) AS sum
                FROM public.campaign
                WHERE (b.brand_id = campaign.brand_id)) AS campaign_budget
        FROM (((((public.organization o
            JOIN public.advertiser a ON ((a.organization_id = o.organization_id)))
            JOIN public.brand b ON ((b.advertiser_id = a.advertiser_id)))
            LEFT JOIN public.campaign c ON ((c.brand_id = b.brand_id)))
            LEFT JOIN public.tracking_unit tu ON ((tu.campaign_id = c.campaign_id)))
            LEFT JOIN temp_mention tm ON ((tm.tracking_unit_id = tu.tracking_unit_id)))
        GROUP BY o.organization_id, a.advertiser_id, b.brand_id
        WITH NO DATA;


        ALTER TABLE public.analytics_rollup_by_brand OWNER TO postgres;

