        -- 20200306000001_lookup_type
        INSERT INTO public.lookup_type (lookup_type_id,lookup_type_name,lookup_type_sql) VALUES 
        (1,'Mention Status','SELECT mention_status_id AS id, mention_status_name AS name, 1 AS type_id FROM mention_status')
        ,(2,'Mention Compliance Status','SELECT mention_compliance_status_id AS id, mention_compliance_status_name AS name, 2 AS type_id FROM mention_compliance_status')
        ,(4,'Mention Spot Type','SELECT spot_type_id AS id, spot_type_name AS name, 4 AS type_id FROM spot_type')
        ,(5,'Market','SELECT arbitron_dma_id AS id, market_name AS name, 5 AS type_id FROM arbitron_dma')
        ,(6,'Gender','SELECT talent_demographic_id AS id, talent_demographic_name AS name, 6 AS type_id FROM talent_demographic WHERE talent_demographic_type_id = 1')
        ,(7,'Language','SELECT talent_demographic_id AS id, talent_demographic_name AS name, 7 AS type_id FROM talent_demographic WHERE talent_demographic_type_id = 2')
        ,(8,'Ethnicity','SELECT talent_demographic_id AS id, talent_demographic_name AS name, 8 AS type_id FROM talent_demographic WHERE talent_demographic_type_id = 3')
        ,(9,'Political','SELECT talent_demographic_id AS id, talent_demographic_name AS name, 9 AS type_id FROM talent_demographic WHERE talent_demographic_type_id = 4')
        ,(10,'Religion','SELECT talent_demographic_id AS id, talent_demographic_name AS name, 10 AS type_id FROM talent_demographic WHERE talent_demographic_type_id = 5')
        ,(11,'Product Category','SELECT product_category_id AS id, product_category_name AS name, 11 AS type_id FROM product_category')
        ,(12,'Radio Program Format','SELECT program_format_id AS id, program_format_name AS name, 12 AS type_id FROM program_format WHERE media_source_type_id = 1')
        ,(13,'TV Program Format','SELECT program_format_id AS id, program_format_name AS name, 13 AS type_id FROM program_format WHERE media_source_type_id = 2')
        ,(14,'Youtube Program Format','SELECT program_format_id AS id, program_format_name AS name, 14 AS type_id FROM program_format WHERE media_source_type_id = 3')
        ,(15,'Podcast Program Format','SELECT program_format_id AS id, program_format_name AS name, 15 AS type_id FROM program_format WHERE media_source_type_id = 4')
        ,(16,'State','SELECT state_id AS id, state_name AS name, 16 AS type_id FROM state')
        ,(17,'Interest','SELECT interest_id AS id, interest_name AS name, 17 AS type_id FROM interest')
        ,(18,'Country','SELECT country_id AS id, country_name AS name, 18 AS type_id FROM country')
        ,(19,'Demographic','SELECT demographic_id AS id, demographic_name AS name, 19 AS type_id FROM demographic')
        ,(20,'Radio Interest','SELECT i.interest_id AS id, i.interest_name AS name, 20 AS type_id FROM interest i, interest__media_source_type im WHERE i.interest_id = im.interest_id AND im.media_source_type_id = 1')
        ,(21,'TV Interest','SELECT i.interest_id AS id, i.interest_name AS name, 21 AS type_id FROM interest i, interest__media_source_type im WHERE i.interest_id = im.interest_id AND im.media_source_type_id = 2')
        ,(22,'YouTube Interest','SELECT i.interest_id AS id, i.interest_name AS name, 22 AS type_id FROM interest i, interest__media_source_type im WHERE i.interest_id = im.interest_id AND im.media_source_type_id = 3')
        ,(23,'Podcast Interest','SELECT i.interest_id AS id, i.interest_name AS name, 23 AS type_id FROM interest i, interest__media_source_type im WHERE i.interest_id = im.interest_id AND im.media_source_type_id = 4')
        ,(3,'Media Source Type','SELECT media_source_type_id AS id, media_source_type_name AS name, 3 AS type_id FROM media_source_type where media_source_type_id <> 5')
        ,(24,'Media Source Type Private Media','SELECT media_source_type_id AS id, media_source_type_name AS name, 24 AS type_id FROM media_source_type')
        ;

