        CREATE TABLE IF NOT EXISTS public.tree_object_content_template (
            tree_object_content_template_id	uuid primary key default uuid_generate_v4(),
            tree_object_id uuid not null references tree_object(tree_object_id),
            sdo_id uuid not null,
            data_registry_id uuid not null,
            creation_date timestamp not null default (current_timestamp AT TIME ZONE 'UTC'),
            last_updated_date timestamp not null default (current_timestamp AT TIME ZONE 'UTC')
        );

        ALTER TABLE public.media_source_type ADD COLUMN IF NOT EXISTS is_live BOOLEAN;
        ALTER TABLE public.media_source_type ADD COLUMN IF NOT EXISTS requires_scan_pipeline BOOLEAN;

        -- needed because source types were manually added to DB with forced IDs past the current sequence state
        alter sequence public.media_source_type_media_source_type_id_seq restart with 20;

        ALTER TABLE public.organization ADD COLUMN IF NOT EXISTS export_formats JSONB not null default '[]'::JSONB;

        ALTER TABLE public.tree_object_content_template ADD COLUMN IF NOT EXISTS deleted_date TIMESTAMP with TIME ZONE;

        alter table public.media_source_type add column if not exists media_source_type_category int4;
        -- legacy source types have direct mapping
        update public.media_source_type set media_source_type_category = 1 where media_source_type_id = 1 and media_source_type_category is null;
        update public.media_source_type set media_source_type_category = 2 where media_source_type_id = 2 and media_source_type_category is null;
        update public.media_source_type set media_source_type_category = 3 where media_source_type_id = 3 and media_source_type_category is null;
        update public.media_source_type set media_source_type_category = 4 where media_source_type_id = 4 and media_source_type_category is null;
        update public.media_source_type set media_source_type_category = 5 where media_source_type_id = 5 and media_source_type_category is null;
        -- new source types need a specific mapping. note that the graphql api will default to 5 (private media/general) if the column
        -- is null. new source types must be created with a source type category id.
        -- youtube
        -- youtube video
        update public.media_source_type set media_source_type_category = 3 where media_source_type_id = 17 and media_source_type_category is null;
        -- youtube live stream
        update public.media_source_type set media_source_type_category = 3 where media_source_type_id = 18 and media_source_type_category is null;
        -- private media
        -- amazon s3
        update public.media_source_type set media_source_type_category = 5 where media_source_type_id = 11 and media_source_type_category is null;
        -- dropbox
        update public.media_source_type set media_source_type_category = 5 where media_source_type_id = 12 and media_source_type_category is null;
        -- ftp
        update public.media_source_type set media_source_type_category = 5 where media_source_type_id = 16 and media_source_type_category is null;

