        -- update audio media source format id
        UPDATE public.media_source
        SET media_source_format_id = CAST(kvp ->> 'formatId' AS INTEGER)
        WHERE media_source_type_id = '1'
        AND media_source_format_id IS NULL
        AND kvp ->> 'formatId' ~ '[0-9]';

        -- update audio media source station channel
        UPDATE public.media_source
        SET station_channel = kvp ->> 'frequency'
        WHERE media_source_type_id = '1'
        AND station_channel IS NULL
        AND kvp ->> 'frequency' > '';

        -- update media sources timezones from links to supported ones
        UPDATE public.media_source SET live_timezone = 'America/Anchorage' WHERE live_timezone = 'US/Alaska';
        UPDATE public.media_source SET live_timezone = 'America/Denver' WHERE live_timezone = 'US/Mountain';
