        CREATE OR REPLACE FUNCTION public.modified_date_time_modified_column() RETURNS TRIGGER AS $$
        BEGIN
        NEW.modified_date_time = CURRENT_TIMESTAMP;
        RETURN NEW;
        END;
        $$ LANGUAGE PLPGSQL;

        CREATE TABLE IF NOT EXISTS public.shared_url (
        id text PRIMARY KEY NOT NULL,
        source_id text NOT NULL DEFAULT '',
        tdo_id text NOT NULL DEFAULT '',
        scheduled_job_id text NOT NULL DEFAULT '',
        start_date_time timestamptz DEFAULT '1970-01-01 00:00:00+00',
        stop_date_time timestamptz DEFAULT '1970-01-01 00:00:00+00',
        start_offset_ms int NOT NULL DEFAULT 0,
        stop_offset_ms int NOT NULL DEFAULT 0,
        settings jsonb NOT NULL DEFAULT '{}',
        service_name text NOT NULL,
        media_type text NOT NULL,
        expire_date timestamptz,
        created_date_time timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
        modified_date_time timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
        );

        ALTER TABLE public.shared_url
        ADD COLUMN IF NOT EXISTS scheduled_job_id text NOT NULL DEFAULT '';

        CREATE INDEX IF NOT EXISTS idx_shared_url_created_date_time ON public.shared_url (created_date_time);

        -- create new schema for partition tables
        CREATE SCHEMA IF NOT EXISTS share;

        -- create child partitions for the rest of the year
        -- Note:  this script below can also be found in ./tools/partition/VTN-12090-shared-url-table-partition.sql
        DO $$
        DECLARE
        startDt DATE := '2018-12-04';
        endDt DATE := '2019-02-28';
        tempRow RECORD;
        partitionName TEXT;
        indexName TEXT;
        BEGIN
        FOR tempRow IN
            SELECT 
            'shared_url_' ||
            to_char(generate_series, 'YYYY_MM_WW')
            AS name
            FROM generate_series(
            startDt::DATE,
            endDt::DATE,
            '7 days'
            )
        LOOP
            partitionName := tempRow.name;

            IF EXISTS(SELECT relname FROM pg_class WHERE relname=partitionName) THEN
            RAISE NOTICE E'\nshare.% table already exists!', partitionName;
            ELSE
            RAISE NOTICE E'\nCreating table share.%', partitionName;
            EXECUTE 'CREATE TABLE share.' || partitionName || ' (CONSTRAINT ' || partitionName || '_no_duplicates UNIQUE (source_id, tdo_id, scheduled_job_id, start_date_time, stop_date_time, start_offset_ms, stop_offset_ms, settings, service_name, media_type)) INHERITS (public.shared_url);';

            indexName := 'idx_' || partitionName || '_created_date_time';
            RAISE NOTICE E'\nCreating index %', indexName;
            EXECUTE 'CREATE INDEX ' || indexName || ' ON share.' || partitionName || ' (created_date_time);';

            RAISE NOTICE E'\nCreating trigger on %s', partitionName;
            EXECUTE 'CREATE TRIGGER update_date_modified BEFORE UPDATE ON share.' || partitionName || ' FOR EACH ROW EXECUTE PROCEDURE public.modified_date_time_modified_column();';
            END IF;
        END LOOP;
        END;
        $$
        LANGUAGE plpgsql;


        DROP TABLE IF EXISTS share.shared_url_2018_11_48;
        DROP TABLE IF EXISTS share.shared_url_2018_12_49;
        DROP TABLE IF EXISTS share.shared_url_2018_12_50;
        DROP TABLE IF EXISTS share.shared_url_2018_12_51;
        DROP TABLE IF EXISTS share.shared_url_2018_12_52;
        DROP TABLE IF EXISTS share.shared_url_2019_01_01;
        DROP TABLE IF EXISTS share.shared_url_2019_01_02;
        DROP TABLE IF EXISTS share.shared_url_2019_01_03;
        DROP TABLE IF EXISTS share.shared_url_2019_01_04;
        DROP TABLE IF EXISTS share.shared_url_2019_01_05;
        DROP TABLE IF EXISTS share.shared_url_2019_02_06;
        DROP TABLE IF EXISTS share.shared_url_2019_02_07;
        DROP TABLE IF EXISTS share.shared_url_2019_02_08;
        DROP TABLE IF EXISTS share.shared_url_2019_02_09;

        CREATE OR REPLACE FUNCTION public.modified_date_time_modified_column() RETURNS TRIGGER AS $$
        BEGIN
            NEW.modified_date_time = CURRENT_TIMESTAMP;
            RETURN NEW;
        END;
        $$ LANGUAGE PLPGSQL;

        -- rename program_id
        ALTER TABLE public.shared_url ADD COLUMN IF NOT EXISTS scheduled_job_id text NOT NULL DEFAULT '';
        ALTER TABLE public.shared_url DROP COLUMN IF EXISTS program_id;

        ALTER TABLE public.shared_url ADD COLUMN IF NOT EXISTS expire_date_time  timestamptz;
        ALTER TABLE public.shared_url DROP COLUMN IF EXISTS expire_date;

        ALTER TABLE public.shared_url DROP COLUMN IF EXISTS created_date_time;
        ALTER TABLE public.shared_url ADD COLUMN created_date_time timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP;

        ALTER TABLE public.shared_url
            ADD COLUMN IF NOT EXISTS modified_date_time timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP;

        -- create shared_url partition tables again
        DO $$
        DECLARE
            startDt DATE := '2018-12-13';
            endDt DATE := '2019-02-28';
            tempRow RECORD;
            partitionName TEXT;
            indexName TEXT;
        BEGIN
            FOR tempRow IN
                SELECT
                    'shared_url_' ||
                    to_char(generate_series, 'YYYY_MM_WW')
                AS name
                FROM generate_series(
                    startDt::DATE,
                    endDt::DATE,
                    '7 days'
                )
            LOOP
                partitionName := tempRow.name;
                IF EXISTS(SELECT relname FROM pg_class WHERE relname=partitionName) THEN
                    RAISE NOTICE E'\nshare.% table already exists!', partitionName;
                ELSE
                    RAISE NOTICE E'\nCreating table share.%', partitionName;
                    EXECUTE 'CREATE TABLE share.' || partitionName || ' (CONSTRAINT ' || partitionName || '_no_duplicates UNIQUE (source_id, tdo_id, scheduled_job_id, start_date_time, stop_date_time, start_offset_ms, stop_offset_ms, settings, service_name, media_type)) INHERITS (public.shared_url);';

                    indexName := 'idx_' || partitionName || '_created_date_time';
                    RAISE NOTICE E'\nCreating index %', indexName;
                    EXECUTE 'CREATE INDEX ' || indexName || ' ON share.' || partitionName || ' (created_date_time);';

                    RAISE NOTICE E'\nCreating trigger on %s', partitionName;
                    EXECUTE 'CREATE TRIGGER update_date_modified BEFORE UPDATE ON share.' || partitionName || ' FOR EACH ROW EXECUTE PROCEDURE public.modified_date_time_modified_column();';

                END IF;
            END LOOP;
        END;
        $$
        LANGUAGE plpgsql;


