        UPDATE public.program SET run_mode = 3 WHERE CAST(start_date_time AS DATE) < '2018-12-01' AND program_name LIKE '%attri%';

        UPDATE public.media_source_type
            SET requires_scan_pipeline = TRUE
            WHERE media_source_type_id = 22 and media_source_type_name = 'Box';

        CREATE TABLE IF NOT EXISTS public.saved_search_profile (
            id	uuid primary key,
            org_id	int not null references organization,
            user_id	uuid not null default uuid_generate_v4(),
            "name"	varchar(255) not null,
            csp	jsonb not null,
            shared_with_org	boolean not null default false,
            created_at	timestamp not null default current_timestamp,
            updated_at	timestamp not null default current_timestamp,
            deleted_at	timestamp,
            UNIQUE (user_id, "name", deleted_at)
        );

        update public.program set v3_job=replace(v3_job::text,', {"engineId": "next-radio"}','')::jsonb where "v3_job"::TEXT like '%next-radio%';


        UPDATE
            public.tree_object
        SET
            shared_with = json_build_object('read', ARRAY [17552]) :: JSONB
        WHERE
            object_id IN
                (
                    SELECT CAST(root_folder_id AS TEXT)
                    FROM public.root_folder
                    WHERE organization_id IN (17548, 17549, 17550, 17551)
                );


        -- Table Definition ----------------------------------------------

        CREATE TABLE IF NOT EXISTS public.shared_collection_history (
            history_id BIGSERIAL NOT NULL PRIMARY KEY,
            history_type text NOT NULL,
            folder_id text NOT NULL,
            share_id text NOT NULL,
            mention_id text,
            status text NOT NULL,
            status_note text,
            retry_count integer NOT NULL DEFAULT 0,
            created_date_time timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
            modified_date_time timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP
        );

        -- Indices -------------------------------------------------------

        CREATE INDEX IF NOT EXISTS shared_collection_history_folder_id_share_id_idx ON public.shared_collection_history(folder_id,share_id);


        INSERT INTO public.tracking_unit_state_lookup (tracking_unit_state_lookup_id, tracking_unit_state_lookup_name) VALUES ( 4, 'INACTIVE') ON CONFLICT DO NOTHING;

        -- Add column user_visible into organization_integration table -------------------
        alter table public.organization_integration add column if not exists user_visible bool;

        -- Add icon for box sourceType
        UPDATE "public"."media_source_type"
            SET "icon_class"='icon-box'
            WHERE "media_source_type_id"='22';
        
        UPDATE
            public.tree_object
        SET
            shared_with = json_build_object('read', ARRAY [17541]) :: JSONB
        WHERE
            object_id IN
                (
                    SELECT CAST(root_folder_id AS TEXT)
                    FROM public.root_folder
                    WHERE organization_id IN (17525, 17530, 17531, 17534, 17535, 17536, 17537, 17538)
                );


        INSERT INTO public.spot_type (spot_type_id, spot_type_name) 
            VALUES (17, 'Bonus'), (18, 'Clipshow')
            ON CONFLICT DO NOTHING;


        DO $$
        BEGIN

        BEGIN
            ALTER TABLE public.shared_url ADD CONSTRAINT shared_url_no_duplicates
                UNIQUE (source_id, tdo_id, scheduled_job_id, start_date_time, stop_date_time, start_offset_ms, stop_offset_ms, settings, service_name, media_type);
        EXCEPTION
            WHEN duplicate_table THEN RAISE NOTICE 'Table constraint shared_url_no_duplicates already exists';
        END;

        END $$
        LANGUAGE plpgsql;


        CREATE TABLE IF NOT EXISTS
            public.custom_dashboard(
                id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
                user_id uuid NOT NULL,
                owner_organization_id int4 NOT NULL REFERENCES organization(organization_id),
                application_id uuid NOT NULL,
                name text NOT NULL,
                description text,
                data jsonb NOT NULL,
                created_date_time timestamptz NOT NULL DEFAULT now(),
                modified_date_time timestamptz NOT NULL DEFAULT now(),
                created_by uuid NOT NULL,
                modified_by uuid NOT NULL
            );


        --- INSERT Root Folder
        INSERT INTO public.root_folder (
            root_folder_id,
            root_folder_type_id,
            organization_id
        )
        SELECT public.uuid_generate_v4(),
            2,
            org.organization_id
        FROM public.organization org
        LEFT JOIN public.root_folder rf
            ON org.organization_id = rf.organization_id
            AND rf.root_folder_type_id = 2
        WHERE rf.organization_id is null
            AND org.organization_id >= 1
        ORDER BY org.organization_id;


        --- INSERT Root folder to tree object
        INSERT INTO public.tree_object (
            tree_object_id,
            object_id,
            tree_object_type_id,
            order_index,
            creation_date,
            last_updated_date,
            tree_object_status
        )
        SELECT public.uuid_generate_v4(),
            rf.root_folder_id,
            4,
            0,
            current_timestamp,
            current_timestamp,
            1
        FROM public.root_folder rf
                LEFT JOIN public.tree_object tro
                        ON CAST(rf.root_folder_id as TEXT) = CAST(tro.object_id as TEXT)
                            AND tro.tree_object_type_id = 4
        WHERE tro.object_id is null;


        --- INSERT CollectiON to tree object
        INSERT INTO public.tree_object (
            tree_object_id,
            object_id,
            tree_object_type_id,
            order_index,
            creation_date,
            last_updated_date,
            tree_object_status
        )
        SELECT public.uuid_generate_v4(),
            f.folder_id,
            3,
            0,
            current_timestamp,
            current_timestamp,
            1
        FROM public.folder f
        LEFT JOIN public.tree_object tro
            ON CAST(f.folder_id as TEXT) = CAST(tro.object_id as TEXT)
            AND tro.tree_object_type_id = 3
        WHERE tro.object_id is null
            AND f.is_active = TRUE;


        ---- INSERT tree_object_id of Root folder to tree object closure
        INSERT INTO public.tree_object_closure (
            depth,
            child_tree_object_id,
            parent_tree_object_id
        )
        SELECT 0,
            tro.tree_object_id,
            tro.tree_object_id
        FROM public.tree_object tro
        LEFT JOIN public.tree_object_closure troc
            ON CAST(tro.tree_object_id as TEXT) = CAST(troc.child_tree_object_id as TEXT)
            AND CAST(tro.tree_object_id as TEXT) = CAST(troc.parent_tree_object_id as TEXT)
            AND tro.tree_object_type_id = 4
        WHERE troc.parent_tree_object_id is null
            AND tro.tree_object_type_id = 4
            AND troc.child_tree_object_id is null;


        ---- INSERT tree_object_id of CollectiON to tree object closure
        INSERT INTO public.tree_object_closure (
            depth,
            child_tree_object_id,
            parent_tree_object_id
        )
        SELECT 0,
            tro.tree_object_id,
            tro.tree_object_id
        FROM public.tree_object tro
                LEFT JOIN public.tree_object_closure troc
                        ON CAST(tro.tree_object_id as TEXT) = CAST(troc.child_tree_object_id as TEXT)
                            AND CAST(tro.tree_object_id as TEXT) = CAST(troc.parent_tree_object_id as TEXT)
                            AND tro.tree_object_type_id = 3
        WHERE troc.parent_tree_object_id is null
        AND tro.tree_object_type_id = 3
        AND troc.child_tree_object_id is null;

        ---- INSERT the relatiONship between object root folder AND object folder to tree object closure
        INSERT INTO public.tree_object_closure (
                depth,
                child_tree_object_id,
                parent_tree_object_id
                )
        SELECT 1,
            tro.tree_object_id,
            obj_root.tree_object_id
        FROM public.tree_object tro
        JOIN public.folder f
            ON CAST(tro.object_id as TEXT) = CAST(f.folder_id as TEXT)
            AND f.is_active = TRUE
        JOIN public.root_folder rf
            ON f.organization_id = rf.organization_id
            AND rf.root_folder_type_id = 2
        LEFT JOIN public.tree_object_closure troc
            ON CAST(tro.tree_object_id as TEXT) = CAST(troc.child_tree_object_id as TEXT)
            AND tro.tree_object_type_id = 3
            AND troc.depth = 1
        JOIN public.tree_object obj_root
            ON obj_root.tree_object_type_id = 4
            AND CAST(rf.root_folder_id as TEXT) = CAST(obj_root.object_id as TEXT)
        WHERE troc.child_tree_object_id is null
            AND tro.tree_object_type_id = 3;


        ALTER TABLE public.program ADD COLUMN IF NOT EXISTS created_by text NULL DEFAULT NULL;

        ALTER TABLE public.custom_dashboard
        ADD COLUMN IF NOT EXISTS host_app_id uuid;

        DO $$
        BEGIN
            IF EXISTS (
                SELECT * 
                FROM information_schema.columns 
                WHERE table_name='custom_dashboard' and column_name='application_id'
            )
            THEN
                ALTER TABLE public.custom_dashboard RENAME COLUMN application_id TO owner_application_id;
            END IF;
        END $$;

        ALTER TABLE public.program
            ADD COLUMN IF NOT EXISTS program_type TEXT default 'job';
    END IF;
END;
